5	/// Enforce the minimal compatibility contract for the Rust OpenAI server.
6	pub(super) fn validate_request_compat(
7	    request: &ChatCompletionRequest,
8	    served_model_names: &[String],
9	) -> Result<(), ApiError> {
10	    if !served_model_names.iter().any(|n| n == &request.model) {
11	        return Err(ApiError::model_not_found(request.model.clone()));
12	    }
13	
14	    if request.stream_options.is_some() && !request.stream {
15	        bail_invalid_request!(
16	            param = "stream_options",
17	            "stream_options are only supported when stream=true."
18	        );
19	    }
20	
21	    if request.n.unwrap_or(1) > 1 {
22	        bail_invalid_request!(param = "n", "Only n=1 is supported.");
23	    }
24	
25	    if request.top_logprobs.is_some() && !request.logprobs {
26	        bail_invalid_request!(
27	            param = "top_logprobs",
28	            "top_logprobs can only be used when logprobs=true."
29	        );
30	    }
31	
32	    if let Some(prompt_logprobs) = request.prompt_logprobs {
33	        if prompt_logprobs < 0 && prompt_logprobs != -1 {
34	            bail_invalid_request!(
35	                param = "prompt_logprobs",
36	                "prompt_logprobs must be a non-negative value or -1."
37	            );
38	        }
39	
40	        if request.stream && (prompt_logprobs > 0 || prompt_logprobs == -1) {
41	            bail_invalid_request!(
42	                param = "prompt_logprobs",
43	                "prompt_logprobs are not available when stream=true."
44	            );
45	        }
46	    }
47	
48	    if let Some(tools) = request.tools.as_ref() {
49	        validate_function_tools(tools, "tools")?;
50	    }
51	
52	    for message in &request.messages {
53	        if let ChatMessage::Developer {
54	            tools: Some(tools), ..
55	        } = message
56	        {
57	            validate_function_tools(tools, "messages[].tools")?;
58	        }
59	    }
60	
61	    if let Some(tool_choice) = &request.tool_choice {
62	        match tool_choice {
63	            ToolChoice::Value(ToolChoiceValue::Auto | ToolChoiceValue::None) => {}
64	            ToolChoice::Value(ToolChoiceValue::Required) => {
65	                bail_invalid_request!(
66	                    param = "tool_choice",
67	                    "tool_choice=required is not supported yet."
68	                );
69	            }
70	            ToolChoice::Function { .. } => {
71	                bail_invalid_request!(
72	                    param = "tool_choice",
73	                    "Named function tool_choice is not supported yet."
74	                );
75	            }
76	            ToolChoice::AllowedTools { .. } => {
77	                bail_invalid_request!(
78	                    param = "tool_choice",
79	                    "allowed_tools tool_choice is not supported yet."
80	                );
81	            }
82	        }
83	    }
84	
85	    if request.use_beam_search {
86	        bail_invalid_request!(
87	            param = "use_beam_search",
88	            "use_beam_search is not supported."
89	        );
90	    }
91	
92	    // ---- Reject parameters that are accepted for deserialization but not yet
93	    // implemented ----
94	
95	    if request.parallel_tool_calls.is_some() {
96	        bail_invalid_request!(
97	            param = "parallel_tool_calls",
98	            "parallel_tool_calls is not supported."
99	        );
100	    }
101	
102	    reject_non_default(
103	        request.length_penalty.as_ref(),
104	        "length_penalty",
105	        "length_penalty is not supported.",
106	    )?;
107	    if !request.spaces_between_special_tokens {
108	        bail_invalid_request!(
109	            param = "spaces_between_special_tokens",
110	            "spaces_between_special_tokens is not supported."
111	        );
112	    }
113	    reject_non_default(
114	        request.truncate_prompt_tokens.as_ref(),
115	        "truncate_prompt_tokens",
116	        "truncate_prompt_tokens is not supported.",
117	    )?;
118	    reject_non_default(
119	        request.thinking_token_budget.as_ref(),
120	        "thinking_token_budget",
121	        "thinking_token_budget is not supported.",
122	    )?;
123	    if !request.include_reasoning {
124	        bail_invalid_request!(
125	            param = "include_reasoning",
126	            "include_reasoning is not supported."
127	        );
128	    }
129	    reject_non_default(
130	        request.media_io_kwargs.as_ref(),
131	        "media_io_kwargs",
132	        "media_io_kwargs is not supported.",
133	    )?;
134	    reject_non_default(
135	        request.mm_processor_kwargs.as_ref(),
136	        "mm_processor_kwargs",
137	        "mm_processor_kwargs is not supported.",
138	    )?;
139	    reject_non_default(
140	        request.repetition_detection.as_ref(),
141	        "repetition_detection",
142	        "repetition_detection is not supported.",
143	    )?;
144	
145	    if let Some(options) = &request.stream_options
146	        && options.continuous_usage_stats.is_some()
147	    {
148	        bail_invalid_request!(
149	            param = "stream_options",
150	            "continuous_usage_stats is not supported."
151	        );
152	    }
153	
154	    Ok(())
155	}
